written_at.fn_text:
export async function toggleVoteAction(workspaceSlug: string, feedbackId: string) {
  const user = await requireUser();

  const feedback = await prisma.feedback.findUnique({
    where: { id: feedbackId },
    include: { workspace: { include: { memberships: { where: { userId: user.id } } } } },
  });
  if (!feedback || feedback.workspace.memberships.length === 0) notFound();

  const existing = await prisma.vote.findUnique({
    where: { feedbackId_userId: { feedbackId, userId: user.id } },
  });

  if (existing) {
    await prisma.vote.delete({ where: { id: existing.id } });
  } else {
    await prisma.vote.create({ data: { feedbackId, userId: user.id } });
  }

  revalidatePath(`/w/${workspaceSlug}`);
  revalidatePath(`/w/${workspaceSlug}/feedback/${feedbackId}`);
}

