const { prisma } = await app("lib/prisma.ts");
const { toggleVoteAction } = await app("lib/actions/feedback.ts");

// Run two toggleVoteAction calls concurrently to simulate race condition
let error1 = null;
let error2 = null;

await Promise.all([
  toggleVoteAction("test-workspace", feedback.id).catch(e => { error1 = e; }),
  toggleVoteAction("test-workspace", feedback.id).catch(e => { error2 = e; }),
]);

// Count votes for the feedback
const voteCount = await prisma.vote.count({ where: { feedbackId: feedback.id } });

record("error1", error1 ? String(error1.message) : null);
record("error2", error2 ? String(error2.message) : null);
record("voteCount", voteCount);

// Harm observed if either call threw a unique constraint violation error
const harmObserved = (error1 && error1.message.includes("Unique constraint failed")) ||
  (error2 && error2.message.includes("Unique constraint failed"));
harm_observed(harmObserved, "Unique constraint violation occurred due to concurrent vote toggling");

const { prisma } = await app("lib/prisma.ts");
const { toggleVoteAction } = await app("lib/actions/feedback.ts");

// Initially no votes
let count = await prisma.vote.count({ where: { feedbackId: feedback.id } });
check(count === 0, "No votes initially");

// Call toggleVoteAction once - should create a vote
await toggleVoteAction("test-workspace", feedback.id);
count = await prisma.vote.count({ where: { feedbackId: feedback.id } });
check(count === 1, "One vote after first toggle");

// Call toggleVoteAction again - should remove the vote
await toggleVoteAction("test-workspace", feedback.id);
count = await prisma.vote.count({ where: { feedbackId: feedback.id } });
check(count === 0, "No votes after second toggle");

const { prisma } = await app("lib/prisma.ts");
const { toggleVoteAction } = await app("lib/actions/feedback.ts");

// Confirm no votes initially
let initialVotes = await prisma.vote.count({ where: { feedbackId: feedback.id } });
check(initialVotes === 0, "No votes initially");

// Call toggleVoteAction once - should create exactly one vote
await toggleVoteAction("test-workspace", feedback.id);
let votesAfterFirstToggle = await prisma.vote.count({ where: { feedbackId: feedback.id } });
check(votesAfterFirstToggle === 1, "One vote after first toggle");

// Call toggleVoteAction again - should remove the vote
await toggleVoteAction("test-workspace", feedback.id);
let votesAfterSecondToggle = await prisma.vote.count({ where: { feedbackId: feedback.id } });
check(votesAfterSecondToggle === 0, "No votes after second toggle");

